import { InsufficientStockError, NotFoundError } from "./domain-errors";
import { OrderLine } from "./order-line";
import { Product } from "./product";
import { ProductRepository } from "./product-repository";

export class StockReservationService {
  constructor(private readonly products: ProductRepository) {}

  /** Reserves every line or none of them. */
  async reserve(lines: readonly OrderLine[]): Promise<void> {
    const loaded: [Product, number][] = [];
    for (const [productId, quantity] of this.totalByProduct(lines)) {
      const product = await this.products.findById(productId);
      if (!product) throw new NotFoundError(`Product ${productId} not found`);
      if (!product.canReserve(quantity)) throw new InsufficientStockError(productId);
      loaded.push([product, quantity]);
    }
    for (const [product, quantity] of loaded) {
      product.reserve(quantity);
      await this.products.save(product);
    }
  }

  async release(lines: readonly OrderLine[]): Promise<void> {
    for (const [productId, quantity] of this.totalByProduct(lines)) {
      const product = await this.products.findById(productId);
      if (!product) continue;
      product.release(quantity);
      await this.products.save(product);
    }
  }

  private totalByProduct(lines: readonly OrderLine[]): Map<string, number> {
    const totals = new Map<string, number>();
    for (const line of lines) {
      totals.set(line.productId, (totals.get(line.productId) ?? 0) + line.quantity);
    }
    return totals;
  }
}

